var n=`0665-ghanaian-jollof-rice`;var t=`world-0665`;var a=`GH`;var o=`western-africa`;var r=4;var s=65;var l={en:`Ghanaian Jollof Rice`,ua:`Рис джолоф по-ганськи`};var g={en:`Ghanaian Jollof Rice is a Ghana classic prepared with yellow onion, red bell pepper, garlic, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Рис джолоф по-ганськи, страва кухні країни Гана зі складниками: жовта цибуля, червоний солодкий перець, часник, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,190,`g`],[`red-bell-pepper`,220,`g`],[`sunflower-oil`,50,`ml`],[`garlic`,3,`clove`]]},{en:`Simmer the liquid and flavorings uncovered for about 15 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 15 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:15,i:[[`tomato`,470,`g`],[`tomato-paste`,60,`g`],[`scotch-bonnet-pepper`,1,`pcs`],[`ground-ginger`,5,`g`]]},{en:`Cook rice over reduced tomato-and-pepper stew, mostly covered and without frequent stirring, so the grains stay separate.`,ua:`Варіть рис у густій томатно-перцевій підливі переважно під кришкою без частого помішування, щоб зерна залишалися окремими.`,t:[`rice-washing`,`absorption-cooking`],m:28,i:[[`basmati-rice`,380,`g`],[`chicken-stock`,650,`ml`],[`bay-leaf`,2,`leaf`]]},{en:`Take off the heat and let the rice rest under a clean towel or lid for about 9 minutes before serving.`,ua:`Зніміть із вогню та дайте рису відпочити під чистим рушником або кришкою приблизно 9 хвилин перед подаванням.`,t:[`rice-resting`,`fluffing-grains`],m:9,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,15,`g`]]}];var c={slug:n,id:t,country:`GH`,region:o,servings:4,minutes:65,title:l,text:g,steps:d};export{a as country,c as default,t as id,s as minutes,o as region,r as servings,n as slug,d as steps,g as text,l as title};